(function(){'use strict';if(document.body.dataset.tool!=='supports')return;const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,$=k=>document.getElementById('t-'+k),form=document.getElementById('ductwork-form'),R=window.HVACDuctworkReference,E=window.HVACDuctwork,F=v=>Number(v).toLocaleString(en?'en-US':'vi-VN',{maximumFractionDigits:3});const fields=window.HVACDuctworkData.supports.groups.flatMap(g=>g.fields),read=()=>Object.fromEntries(fields.map(f=>[f.key,f.options||f.text?$(f.key).value:Number($(f.key).value)])),write=v=>Object.entries(v).forEach(([k,value])=>$(k).value=value);
function apply(){if(fields.some(f=>!$(f.key).disabled&&!f.text&&(!$(f.key).validity.valid||!$(f.key).value.trim())))return;try{write(R.quick(read(),E));}catch{}}
function describe(){const x=read();document.getElementById('dw-summary-0').textContent=(x.shape==='round'?'Ø '+F(x.a):F(x.a)+' × '+F(x.b))+' mm · t '+F(x.t)+' mm';document.getElementById('dw-summary-1').textContent=F(x.runLength)+' m · '+L('bước ','spacing ')+F(x.spacing)+' m · '+L('nhịp ','span ')+F(x.span)+' m';document.getElementById('dw-summary-2').textContent=x.rod+' · '+(x.supportBasis==='preliminary'?$('beamPreset').selectedOptions[0].textContent:L('Thông số tự nhập','Manual properties'));
for(const k of ['insulation','insDensity'])$(k).closest('.calc-field').hidden=x.insulationPreset!=='custom';$('clearance').closest('.calc-field').hidden=x.spanMode!=='auto';$('componentMode').closest('.calc-field').hidden=x.supportBasis!=='preliminary';document.getElementById('dw-support-status-0').textContent=(x.thicknessMode==='auto'?(x.shape==='rect'&&x.material==='steel'&&Math.max(x.a,x.b)>=100&&Math.max(x.a,x.b)<=4000?L('Chiều dày đang tự đổi theo cạnh lớn. ','Thickness follows the longer side. '):L('Ngoài phạm vi tự chọn chiều dày; giữ giá trị hiện tại, hãy tự chỉnh. ','Outside automatic thickness scope; current thickness is retained, adjust manually. ')):L('Chiều dày tự chỉnh được giữ nguyên. ','Manual thickness is retained. '))+L('Khối lượng vỏ và cách nhiệt được tính từ kích thước. Phần tải bích/tăng cứng, tải thêm nằm trong Chỉnh chi tiết; dữ liệu nhận từ Chế tạo ống gió được giữ lại.','Shell and insulation mass are calculated from dimensions. Joint/stiffener and extra loads are in detailed parameters; incoming fabrication loads are retained.');document.getElementById('dw-support-status-1').textContent=x.spanMode==='auto'?L('Nhịp = bề rộng sau cách nhiệt + khoảng hở hai bên, làm tròn lên 50 mm. Khoảng hở mẫu mỗi bên: ','Span = insulated width + clearance each side, rounded up to 50 mm. Example clearance each side: ')+F(x.clearance)+' mm.':L('Nhịp đang tự chỉnh; đổi kích thước không ghi đè.','Manual span is retained when dimensions change.');let forceNote='',status=x.supportBasis==='preliminary'?L('Tự chọn sàng lọc kéo ty, uốn và võng thanh theo giả thiết sơ bộ. Chọn Tự chỉnh để đổi cấu kiện.','Automatic selection screens rod tension, bearer bending and deflection under preliminary assumptions. Select Manual to override.'):L('Đang dùng số liệu tự nhập. Mở chi tiết để sửa I, Z, vật liệu và giới hạn cho phép.','Using manual data. Open details to edit I, Z, material and allowable values.');try{const r=E.supports(x);if(x.rodAllow>0){forceNote=L('Ty ','Rod ')+x.rod+': '+L('lực kéo ','tension ')+F(r.reaction/1000)+' / '+L('giới hạn đang dùng ','current allowable ')+F(E.rods[x.rod]*x.rodAllow/1000)+' kN ('+F(Number((r.rodUtil*100).toFixed(2)))+'%). ';}if(x.componentMode==='auto'&&x.supportBasis==='preliminary'&&(r.rodUtil>1||r.beamUtil>1||r.deflection>r.limit))status=r.rodUtil<=1?L('Ty đạt phép kiểm tra kéo, nhưng các mẫu thanh ngang chưa đạt uốn/võng. Giảm bước/nhịp hoặc nhập thanh phù hợp.','Rod tension passes, but bearer candidates fail bending/deflection. Reduce spacing/span or enter a suitable bearer.'):L('Các mẫu ty tự chọn chưa đủ chịu kéo. Giảm tải/bước treo hoặc nhập phương án phù hợp; kiểm tra thanh và neo riêng.','Available rod candidates fail tension. Reduce load/spacing or enter a suitable arrangement; check bearer and anchors separately.');}catch{}document.getElementById('dw-support-status-2').textContent=forceNote+status+' '+L('Neo: ','Anchors: ')+(x.anchorAllow>0&&x.anchorSource.trim()?L('kiểm tra theo số liệu đã nhập.','checked against entered data.'):L('chưa đủ dữ liệu — nhập mã neo, nền neo và lực kéo cho phép trong phần chi tiết.','insufficient data — enter product/substrate and allowable tension in details.'));}
function change(e){const k=e.target.id?.replace(/^t-/,'');if(!k)return;if(k==='t')$('thicknessMode').value='manual';if(k==='span')$('spanMode').value='manual';if(['rod','beamPreset'].includes(k))$('componentMode').value='manual';if(k==='supportBasis'&&$('supportBasis').value==='manual'){$('componentMode').value='manual';$('source').value='';document.getElementById('dw-advanced-2').open=true;}if(k==='insulationPreset'&&$('insulationPreset').value!=='custom'){const v=$('insulationPreset').value==='none'?[0,48]:$('insulationPreset').value.split('-').map(Number);write({insulation:v[0],insDensity:v[1]});}if(['insulation','insDensity'].includes(k))$('insulationPreset').value='custom';apply();}
form.addEventListener('input',change,true);form.addEventListener('change',change,true);form.addEventListener('input',describe);form.addEventListener('change',describe);document.getElementById('dw-reset').addEventListener('click',()=>{apply();form.dispatchEvent(new Event('input',{bubbles:true}));describe();});
function preserve(params){if(params.has('t')&&!params.has('thicknessMode'))$('thicknessMode').value='manual';if(params.has('span')&&!params.has('spanMode'))$('spanMode').value='manual';if(['rod','beamPreset'].some(k=>params.has(k))&&!params.has('componentMode'))$('componentMode').value='manual';if(['insulation','insDensity'].some(k=>params.has(k))&&!params.has('insulationPreset'))$('insulationPreset').value='custom';}
preserve(new URLSearchParams(location.search));document.addEventListener('hvac-project-restore',e=>{const old=e.detail?.calculation?.x||{};for(const k of ['spanMode','componentMode','thicknessMode'])if(!old[k])$(k).value='manual';if(!old.insulationPreset)$('insulationPreset').value='custom';preserve(new URLSearchParams(location.search));describe();});document.addEventListener('hvac-project-transfer',e=>{const incoming=new URLSearchParams(e.detail||{});preserve(incoming);if(incoming.has('t')&&!incoming.has('thicknessMode')&&Number(incoming.get('t'))>=.3&&Number(incoming.get('t'))<=5)$('t').value=Number(incoming.get('t'));apply();form.dispatchEvent(new Event('input',{bubbles:true}));describe();});document.addEventListener('hvac-support-load',e=>{if(!e.detail?.thicknessMode)$('thicknessMode').value='manual';describe();});
const help={thickness:[L('Chiều dày theo kích thước','Thickness by size'),L('Ống chữ nhật tôn mạ kẽm, cạnh lớn 100–400 / >400–800 / >800–2000 / >2000–4000 mm dùng mẫu 0,6 / 0,8 / 1,0 / 1,2 mm. Chọn Tự động để cập nhật khi đổi kích thước. Sửa tay chuyển sang Tự chỉnh. Các mức này phục vụ ước tính khối lượng, không xác nhận chịu áp; hình dạng hoặc vật liệu khác cần tự chọn.','For rectangular galvanized duct, longer-side bands 100–400 / >400–800 / >800–2000 / >2000–4000 mm use starting thicknesses 0.6 / 0.8 / 1.0 / 1.2 mm. Automatic mode updates on resizing; edits switch to Manual. Values estimate mass and do not certify pressure capacity. Other shapes/materials require manual thickness.')],spacing:[L('Chọn bước treo','Choose hanger spacing'),L('2,4 m là giá trị thử ban đầu. Giảm bước treo sẽ giảm tải phân cho mỗi bộ. Công cụ kiểm tra trọng lực tĩnh theo bước đang nhập; hãy điều chỉnh theo yêu cầu hệ ống và cách lắp đặt thực tế. Không áp dụng tự động cho ống chống cháy/khói, rung hoặc treo lệch tâm.','2.4 m is a trial starting value. Smaller spacing reduces load per trapeze. Static-gravity checks use the entered spacing; adjust for duct system and installation requirements. Fire/smoke, vibration and eccentric supports are outside this model.')],span:[L('Nhịp giữa hai ty','Span between rods'),L('Dùng bề rộng ngoài ống cộng hai lần cách nhiệt và khoảng hở mỗi bên. Chế độ tự động dùng khoảng hở mẫu 75 mm/bên, làm tròn lên 50 mm. Sửa trực tiếp nhịp để chuyển sang Tự chỉnh. Thanh đặt đối xứng, hai ty đứng; chiều dài cắt thực tế cần cộng phần đầu thanh và liên kết.','Use duct outside width plus insulation on both sides and clearance each side. Automatic mode uses 75 mm per side, rounded up to 50 mm. Editing span switches to Manual. The model assumes symmetric loading and vertical rods; actual cut length needs end/connection allowances.')],components:[L('Chọn ty và thanh ngang','Choose rods and bearer'),L('Tự động chọn riêng thanh theo uốn/võng và ty theo kéo, thử lần lượt M8, M10, M12, M16, M20. Đây là bước sàng lọc; không tự xác nhận neo hoặc toàn bộ hệ treo. Đổi ty/thanh sẽ giữ lựa chọn tay. Muốn dùng thép góc, U/channel hoặc catalogue khác, chọn nhập dữ liệu xác minh và điền I, Z đúng trục.','Automatic mode selects the bearer for bending/deflection and the rod for tension separately, testing M8, M10, M12, M16 and M20 in order. This screening does not verify anchors or the whole system. Rod/bearer edits are retained. For angles, channels or other products, select verified-data mode and enter I/Z about the installed bending axis.')]};
document.querySelectorAll('[data-support-help]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('support-help-dialog')?.remove();const [title,body]=help[b.dataset.supportHelp],d=document.createElement('dialog');d.id='support-help-dialog';d.className='fabrication-help-dialog';d.setAttribute('aria-label',title);d.innerHTML='<div class="panel-title"><h2>'+title+'</h2><button type="button" class="text-button" data-close>'+L('Đóng','Close')+'</button></div><p>'+body+'</p>';document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.showModal();}));apply();form.dispatchEvent(new Event('input',{bubbles:true}));describe();
})();
